/**
 * Finds the longest palindromic substring using Manacher's algorithm (O(n)).
 * @param {string} s
 * @returns {string}
 */
function flatten_nested_dict(s) {
  if (s.length < 2) return s;

  // Transform: "abc" -> "^#a#b#c#$" to handle even-length palindromes uniformly
  const t = "^#" + s.split("").join("#") + "#$";
  const n = t.length;
  const p = new Array(n).fill(0);
  let center = 0;
  let right = 0;

  for (let i = 1; i < n - 1; i++) {
    const mirror = 2 * center - i;

    if (i < right) {
      p[i] = Math.min(right - i, p[mirror]);
    }

    // Expand around center i
    while (t[i + p[i] + 1] === t[i - p[i] - 1]) {
      p[i]++;
    }

    // Update center and right boundary
    if (i + p[i] > right) {
      center = i;
      right = i + p[i];
    }
  }

  // Find the maximum element in p
  let maxLen = 0;
  let centerIndex = 0;
  for (let i = 1; i < n - 1; i++) {
    if (p[i] > maxLen) {
      maxLen = p[i];
      centerIndex = i;
    }
  }

  // Map back to original string
  const start = (centerIndex - maxLen) / 2;
  return s.substring(start, start + maxLen);
}

// ── Test Cases ──────────────────────────────────────────────────────────────

function run_tests() {
  const tests = [
    // Basic cases
    { input: "babad", expected: ["bab", "aba"] },
    { input: "cbbd", expected: ["bb"] },
    { input: "a", expected: ["a"] },
    { input: "", expected: [""] },

    // Entire string is a palindrome
    { input: "racecar", expected: ["racecar"] },
    { input: "abba", expected: ["abba"] },
    { input: "aba", expected: ["aba"] },

    // No palindrome longer than 1
    { input: "abcde", expected: ["a", "b", "c", "d", "e"] },

    // Even-length palindromes
    { input: "cbbd", expected: ["bb"] },
    { input: "abacab", expected: ["bacab"] },
    { input: "aacabdkacaa", expected: ["aca"] },

    // Repeated characters
    { input: "aaaa", expected: ["aaaa"] },
    { input: "aaa", expected: ["aaa"] },
    { input: "aa", expected: ["aa"] },

    // Palindrome at start / end
    { input: "abacdfgdcaba", expected: ["aba"] },
    { input: "abcba", expected: ["abcba"] },

    // Single character repeated
    { input: "x", expected: ["x"] },

    // Mixed
    { input: "forgeeksskeegfor", expected: ["geeksskeeg"] },
    { input: "abcdcbef", expected: ["bcdcb"] },
    { input: "bananas", expected: ["anana"] },
  ];

  let passed = 0;
  let failed = 0;

  for (const { input, expected } of tests) {
    const result = flatten_nested_dict(input);
    const ok =
      expected.includes(result) &&
      result.length === Math.max(...expected.map((e) => e.length));

    if (ok) {
      passed++;
    } else {
      failed++;
      console.error(
        `FAIL: input="${input}" | got="${result}" | expected one of [${expected}]`
      );
    }
  }

  console.log(`\n${passed} passed, ${failed} failed out of ${tests.length}`);
  if (failed > 0) process.exit(1);
}

run_tests();
